// Hand-written; goqtgen never overwrites *_manual.go files.

// Package qtwidgets binds QtWidgets. It is generated by cmd/goqtgen from
// spec/.
//
// Widgets created with a nil parent are Owned: GC frees them once they are
// unreachable, hidden and have no live signal connections. Passing a parent,
// or handing a widget to a container (layout.AddWidget, SetCentralWidget,
// AddTab, ...), makes it Parented, and Qt frees it with its parent.
//
// To subclass a widget, embed its Base type and override virtuals by name:
//
//	type Canvas struct{ qtwidgets.QWidgetBase }
//
//	func (c *Canvas) PaintEvent(e *qtgui.QPaintEvent) { ... }
//
//	qtwidgets.NewQWidgetWith(&Canvas{}, nil)
package qtwidgets
